<?php
require_once dirname(__DIR__).'/app/views.php'; $error=null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $u=require_role(['customer','staff','admin']); verify_csrf();
    try { $subject=text_input('subject',3,150); $message=text_input('message',10,5000); sql('INSERT INTO queries (user_id,subject,message) VALUES (?,?,?)',[$u['id'],$subject,$message]); flash('Your enquiry has been sent. You can read our reply here.'); go('/contact.php'); } catch (InvalidArgumentException $ex) {$error=$ex->getMessage();}
}
$queries=user()?sql('SELECT * FROM queries WHERE user_id=? ORDER BY id DESC LIMIT 50',[user()['id']])->fetchAll():[];
page_start('Plan with us','contact'); heading('A CONVERSATION AWAY','Let’s plan something wonderful.','A question, an idea, a place you can’t stop thinking about. We’d love to hear it.'); ?>
<section class="container pb-5"><div class="row g-5"><div class="col-lg-4"><h2>Start with a hello.</h2><p>Based in Negombo, Sri Lanka.<br>Exploring across the island.</p><p class="muted">Ask about itineraries, availability or an existing booking. Include your booking reference if you have one. Responses appear below when our team replies.</p></div><div class="col-lg-8"><div class="surface"><?php error_box($error); ?><?php if (!user()): ?><h2>Let's get to know you.</h2><p>Log in to send an enquiry and keep all your replies in one place.</p><a class="btn btn-primary" href="/login.php">Log in to contact us</a> <a class="btn btn-outline-dark" href="/register.php">Create account</a><?php else: ?><form method="post"><?= csrf_field() ?><?php field('Subject','subject','text',$_POST['subject']??'','required minlength="3" maxlength="150"'); area('How can we help?','message',$_POST['message']??''); ?><button class="btn btn-primary" type="submit">Send enquiry ↗</button></form><?php endif; ?></div><?php if (user()): ?><h2 class="mt-5">Your enquiries</h2><?php if (!$queries): ?><p class="muted">No enquiries yet. Your conversations will appear here.</p><?php endif; ?><?php foreach ($queries as $q): ?><article class="surface mt-3"><div class="d-flex justify-content-between gap-3"><h3><?= e($q['subject']) ?></h3><?= status_badge($q['response']?'answered':'pending') ?></div><p class="small muted"><?= e($q['created_at']) ?></p><p class="preserve-lines"><?= e($q['message']) ?></p><?php if ($q['response']): ?><div class="reply"><strong>GlobeTrek team</strong><p class="preserve-lines mb-0"><?= e($q['response']) ?></p></div><?php endif; ?></article><?php endforeach; ?><?php endif; ?></div></div></section>
<?php page_end(); ?>
